reader = csv.reader(io.StringIO(raw_csv_text))
header = next(reader)

def clean_col_name(c):
    c = c.strip()
    c = re.sub(r'[\'\"()/?.,-]+', '_', c)
    c = re.sub(r'\s+', '_', c)
    c = re.sub(r'_+', '_', c)
    c = c.strip('_').lower()
    return c

clean_headers = []
seen = {}
for h in header:
    ch = clean_col_name(h)
    if not ch:
        ch = "col"
    if ch in seen:
        seen[ch] += 1
        ch = f"{ch}_{seen[ch]}"
    else:
        seen[ch] = 1
    clean_headers.append(ch)

rows = list(reader)

# Build SQL CREATE TABLE
sql_lines = []
sql_lines.append("-- SQL Schema & Seed Data generated for Dibrugarh Town Directory Census Dataset\n")
sql_lines.append("CREATE TABLE IF NOT EXISTS public.dibrugarh_town_directory (")
col_defs = []
for h in clean_headers:
    col_defs.append(f"  {h} TEXT")
sql_lines.append(",\n".join(col_defs))
sql_lines.append(");\n")

# Build SQL INSERT STATEMENTS
for row in rows:
    cleaned_vals = []
    for val in row:
        val_str = val.strip().strip("'")
        if val_str.upper() == 'NA' or val_str == '' or val_str == '--':
            cleaned_vals.append("NULL")
        else:
            val_escaped = val_str.replace("'", "''")
            cleaned_vals.append(f"'{val_escaped}'")
    
    cols_str = ", ".join(clean_headers)
    vals_str = ", ".join(cleaned_vals)
    sql_lines.append(f"INSERT INTO public.dibrugarh_town_directory ({cols_str}) VALUES ({vals_str});")

output_sql = "\n".join(sql_lines)

with open("supabase/dibrugarh_town_directory.sql", "w", encoding="utf-8") as f:
    f.write(output_sql)

print(f"Successfully generated SQL table with {len(clean_headers)} columns and {len(rows)} town rows.")
